<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{getSupplierProducts,getSupplierProduct}from'../../api/supplierProduct';import{getSuppliers}from'../../api/supplier';import type{Supplier,SupplierProduct}from'../../api/types'
const rows=ref<SupplierProduct[]>([]),suppliers=ref<Supplier[]>([]),total=ref(0),loading=ref(false),detail=ref<SupplierProduct>(),detailVisible=ref(false);const query=reactive({supplierId:undefined as number|undefined,pageNum:0,pageSize:10})
async function load(){loading.value=true;try{const d=await getSupplierProducts(query);rows.value=d.list||[];total.value=d.total||0}catch(e:any){ElMessage.error(e.message||'加载失败')}finally{loading.value=false}}async function loadSuppliers(){try{const d=await getSuppliers({pageNum:0,pageSize:100});suppliers.value=d.list||[]}catch(e:any){ElMessage.error(e.message||'供应商加载失败')}}async function show(r:SupplierProduct){try{detail.value=await getSupplierProduct(r.id);detailVisible.value=true}catch(e:any){ElMessage.error(e.message||'加载详情失败')}}onMounted(()=>{load();loadSuppliers()})
</script>
<template><div><div class="page-title"><div><h2>供应商商品编码</h2><p>查看供应商货号与 Barcode 映射</p></div></div><el-card shadow="never"><el-form :inline="true"><el-form-item label="供应商"><el-select v-model="query.supplierId" clearable placeholder="全部" style="width:220px"><el-option v-for="s in suppliers" :key="s.id" :label="s.supplierName" :value="s.id"/></el-select></el-form-item><el-form-item><el-button type="primary" @click="query.pageNum=0;load()">查询</el-button></el-form-item></el-form><el-table :data="rows" v-loading="loading" stripe><el-table-column prop="id" label="ID" width="80"/><el-table-column prop="supplierId" label="供应商ID" width="110"/><el-table-column prop="supplierCode" label="供应商货号" min-width="180"/><el-table-column prop="barcode" label="Barcode" min-width="180"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status===false?'danger':'success'">{{row.status===false?'停用':'正常'}}</el-tag></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="show(row)">详情</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination :current-page="query.pageNum+1" :page-size="query.pageSize" :total="total" layout="total,prev,pager,next" @current-change="(p:number)=>{query.pageNum=p-1;load()}"/></div></el-card><el-dialog v-model="detailVisible" title="供应商商品详情" width="520px"><el-descriptions v-if="detail" :column="1" border><el-descriptions-item label="ID">{{detail.id}}</el-descriptions-item><el-descriptions-item label="供应商ID">{{detail.supplierId??'-'}}</el-descriptions-item><el-descriptions-item label="供应商货号">{{detail.supplierCode||'-'}}</el-descriptions-item><el-descriptions-item label="Barcode">{{detail.barcode||'-'}}</el-descriptions-item><el-descriptions-item label="状态">{{detail.status===false?'停用':'正常'}}</el-descriptions-item><el-descriptions-item label="创建时间">{{detail.createdAt||'-'}}</el-descriptions-item><el-descriptions-item label="更新时间">{{detail.updatedAt||'-'}}</el-descriptions-item></el-descriptions></el-dialog></div></template>
